        optAutoTranslateDesc: 'हर खुलने वाले पृष्ठ का बिना पूछे अनुवाद करता है। बहिष्कृत साइटें और पहले से आपकी भाषा वाले पृष्ठ छोड़ दिए जाते हैं, और कुछ ऐप जैसी साइटें फिर भी पहले पूछती हैं।',
        optNeverAskDesc: 'सभी साइटों पर पुष्टि संदेश छिपाता है। जो पृष्ठ अपने आप अनुवादित नहीं होते वे मूल भाषा में ही रहते हैं; उन्हें टूलबार से शुरू करना होगा।',
        optStreamingDesc: 'अनुवाद जैसे-जैसे प्राप्त होता है, पृष्ठ पर क्रमशः दिखाता है',
        optProgressDesc: 'अनुवाद के दौरान पृष्ठ पर प्रगति पैनल दिखाता है',
        optContextMenuDesc: 'राइट-क्लिक मेनू में मूल पाठ और अनुवाद बदलने तथा चयनित टेक्स्ट का अनुवाद करने के विकल्प जोड़ता है। चयनित टेक्स्ट का अनुवाद केवल इसी मेनू से होता है।',
        optAutoRetranslateDesc: 'किसी साइट का एक पेज अनुवाद करने पर उसी साइट के बाकी पेज अपने आप अनुवादित होते हैं। यह केवल तब तक चलता है जब तक उस साइट का कम से कम एक टैब खुला हो। स्थायी नियम के लिए “हमेशा अनुवाद होने वाली साइटें” का उपयोग करें।',
        optExcludeListDesc: 'इन साइटों पर न स्वचालित अनुवाद होगा, न पुष्टि संदेश दिखेगा। टूलबार से आप इन्हें स्वयं अनुवाद कर सकते हैं।',
        optMaxTokenDesc: 'प्रति अनुरोध AI के आउटपुट की अधिकतम सीमा',
