        optDelayDesc: 'एक ही पृष्ठ से भेजे जाने वाले अनुरोधों के बीच न्यूनतम अंतर, दर सीमा से बचने के लिए',
        optConcurrencyDesc: 'एक पृष्ठ एक साथ कितने अनुरोध भेज सकता है। हर टैब की गिनती अलग होती है, इसलिए खुले टैब कुल संख्या बढ़ा देते हैं।',
        optRetriesDesc: 'असफल अनुरोध को कितनी बार दोहराया जाए। गलत API कुंजी जैसी स्थायी त्रुटियों पर दोबारा प्रयास नहीं होता।',
