        optNeverAskDesc: 'সব সাইটে নিশ্চিতকরণ বার্তা লুকিয়ে রাখে। যেসব পৃষ্ঠা স্বয়ংক্রিয়ভাবে অনুবাদ হয় না সেগুলো মূল ভাষাতেই থাকে, টুলবার থেকে শুরু করতে হয়।',
        optStreamingDesc: 'অনুবাদ আসতে আসতেই পৃষ্ঠায় ধাপে ধাপে দেখায়',
        optProgressDesc: 'অনুবাদ চলাকালীন পৃষ্ঠায় অগ্রগতি প্যানেল দেখায়',
        optContextMenuDesc: 'ডান-ক্লিক মেনুতে মূল পাঠ ও অনুবাদ বদলের এবং নির্বাচিত লেখা অনুবাদের বিকল্প যোগ করে। নির্বাচিত লেখা অনুবাদের একমাত্র উপায় এই মেনু।',
        optAutoRetranslateDesc: 'কোনো সাইটের একটি পৃষ্ঠা অনুবাদ করলে সেই সাইটের বাকি পৃষ্ঠাগুলোও স্বয়ংক্রিয়ভাবে অনুবাদ হয়। সেই সাইটের অন্তত একটি ট্যাব খোলা থাকা পর্যন্তই এটি চলে। স্থায়ীভাবে চালু রাখতে “সবসময় অনুবাদ হওয়া সাইট” ব্যবহার করুন।',
        optExcludeListDesc: 'এই সাইটগুলিতে স্বয়ংক্রিয় অনুবাদ হয় না, নিশ্চিতকরণ বার্তাও দেখানো হয় না। টুলবার থেকে আপনি নিজে অনুবাদ করতে পারবেন।',
        optMaxTokenDesc: 'প্রতি অনুরোধে AI-এর আউটপুটের সর্বোচ্চ সীমা',
        optAnthropicMaxTokenDesc: 'প্রতি অনুরোধে AI-এর আউটপুটের সর্বোচ্চ সীমা। Anthropic সর্বোচ্চ {limit} পর্যন্ত গ্রহণ করে',
        optDelayDesc: 'একই পৃষ্ঠা থেকে পাঠানো অনুরোধগুলির মধ্যে ন্যূনতম বিরতি, হার-সীমা এড়াতে',
        optConcurrencyDesc: 'একটি পৃষ্ঠা একসঙ্গে কতগুলি অনুরোধ পাঠাতে পারে। প্রতিটি ট্যাব আলাদাভাবে গোনা হয়, তাই খোলা ট্যাব যত বেশি মোট সংখ্যাও তত বাড়ে।',
        optRetriesDesc: 'ব্যর্থ অনুরোধ কতবার আবার চেষ্টা করা হবে। ভুল API কী-এর মতো স্থায়ী ত্রুটিতে আবার চেষ্টা করা হয় না।',
