        optAutoRetranslateDesc: 'ఒక సైట్‌లోని ఒక పేజీని అనువదిస్తే, ఆ సైట్‌లోని మిగతా పేజీలు కూడా ఆటోమేటిక్‌గా అనువదించబడతాయి. ఆ సైట్ ట్యాబ్ కనీసం ఒకటి తెరిచి ఉన్నంత వరకే ఇది పనిచేస్తుంది. శాశ్వత నియమం కోసం “ఎల్లప్పుడూ అనువదించే సైట్‌లు” ఉపయోగించండి.',
        optExcludeListDesc: 'ఈ సైట్‌లలో ఆటో అనువాదం జరగదు, నిర్ధారణ సందేశమూ కనిపించదు. టూల్‌బార్ నుండి మీరే అనువదించవచ్చు.',
        optMaxTokenDesc: 'ప్రతి అభ్యర్థనకు AI ఇవ్వగల గరిష్ఠ పరిమితి',
        optAnthropicMaxTokenDesc: 'ప్రతి అభ్యర్థనకు AI ఇవ్వగల గరిష్ఠ పరిమితి. Anthropic గరిష్ఠంగా {limit} వరకు మాత్రమే అంగీకరిస్తుంది',
        optDelayDesc: 'ఒకే పేజీ పంపే అభ్యర్థనల మధ్య కనీస వ్యవధి, రేటు పరిమితిని తప్పించడానికి',
        optConcurrencyDesc: 'ఒక పేజీ ఒకేసారి పంపగల అభ్యర్థనల సంఖ్య. ప్రతి ట్యాబ్ విడిగా లెక్కించబడుతుంది, కాబట్టి తెరిచిన ట్యాబ్‌లు మొత్తాన్ని పెంచుతాయి.',
        optRetriesDesc: 'విఫలమైన అభ్యర్థనను ఎన్నిసార్లు మళ్లీ ప్రయత్నించాలి. తప్పు API కీ వంటి శాశ్వత లోపాలకు మళ్లీ ప్రయత్నించదు.',
