        optEndpointDesc: 'OpenAI-இணக்கமான chat completions முனையத்தின் முழு URL',
        optCompatibleApiKeyDesc: 'விருப்பத்திற்குரியது. இந்தச் சாதனத்தில் மட்டுமே சேமிக்கப்படுகிறது; மேலே உள்ள முனையத்திற்கு மட்டுமே அனுப்பப்படுகிறது',
        optCompatibleModelDesc: 'கட்டாயம். மேலே உள்ள முனையம் ஏற்கும் மாடல் ID ஐ உள்ளிடவும்',
        optAutoTranslateDesc: 'நீங்கள் திறக்கும் ஒவ்வொரு பக்கத்தையும் கேட்காமல் மொழிபெயர்க்கும். விலக்கிய தளங்களும் ஏற்கெனவே உங்கள் மொழியில் உள்ள பக்கங்களும் தவிர்க்கப்படும்; சில செயலி பாணி தளங்கள் இருப்பினும் முதலில் கேட்கும்.',
        optNeverAskDesc: 'எல்லா தளங்களிலும் உறுதிப்படுத்தல் செய்தியை மறைக்கும். தானாக மொழிபெயர்க்கப்படாத பக்கங்கள், கருவிப்பட்டியிலிருந்து தொடங்கும் வரை மூல மொழியிலேயே இருக்கும்.',
        optStreamingDesc: 'மொழிபெயர்ப்பு வந்தவுடன் பக்கத்தில் படிப்படியாகக் காட்டும்',
        optProgressDesc: 'மொழிபெயர்க்கும் போது பக்கத்தில் முன்னேற்றப் பலகையைக் காட்டும்',
        optContextMenuDesc: 'வலது கிளிக் மெனுவில் மூல உரை/மொழிபெயர்ப்பு மாற்றும், தேர்ந்தெடுத்த உரையை மொழிபெயர்க்கும் விருப்பங்களைச் சேர்க்கும். தேர்ந்தெடுத்த உரையை மொழிபெயர்க்க இதுவே ஒரே வழி.',
        optAutoRetranslateDesc: 'ஒரு தளத்தின் ஒரு பக்கத்தை மொழிபெயர்த்ததும், அதே தளத்தின் மற்ற பக்கங்களும் தானாக மொழிபெயர்க்கப்படும். அந்தத் தளத்தின் ஒரு தாவலாவது திறந்திருக்கும் வரை மட்டுமே இது நீடிக்கும். நிரந்தர விதிக்கு “எப்போதும் மொழிபெயர்க்கப்படும் தளங்கள்” பயன்படுத்தவும்.',
        optExcludeListDesc: 'இந்தத் தளங்களில் தானியங்கி மொழிபெயர்ப்போ உறுதிப்படுத்தல் செய்தியோ இருக்காது. கருவிப்பட்டியிலிருந்து நீங்களே மொழிபெயர்க்கலாம்.',
        optMaxTokenDesc: 'ஒரு கோரிக்கையில் AI வெளியிடக்கூடிய உச்ச வரம்பு',
        optAnthropicMaxTokenDesc: 'ஒரு கோரிக்கையில் AI வெளியிடக்கூடிய உச்ச வரம்பு. Anthropic அதிகபட்சம் {limit} வரை மட்டுமே ஏற்கும்',
        optDelayDesc: 'ஒரே பக்கம் அனுப்பும் கோரிக்கைகளுக்கு இடையிலான குறைந்தபட்ச இடைவெளி, வீத வரம்பைத் தவிர்க்க',
        optConcurrencyDesc: 'ஒரு பக்கம் ஒரே நேரத்தில் அனுப்பக்கூடிய கோரிக்கைகளின் எண்ணிக்கை. ஒவ்வொரு தாவலும் தனித்தனியாக கணக்கிடப்படுவதால், திறந்த தாவல்கள் மொத்தத்தைப் பெருக்கும்.',
        optRetriesDesc: 'தோல்வியடைந்த கோரிக்கையை எத்தனை முறை மீண்டும் முயற்சிப்பது. தவறான API விசை போன்ற நிரந்தரப் பிழைகள் மீண்டும் முயற்சிக்கப்படாது.',
        optTimeoutDesc: 'ஒரு கோரிக்கையின் பதிலுக்கான அதிகபட்ச காத்திருப்பு நேரம். ஒரு பக்கத்திற்கு பொதுவாக பல கோரிக்கைகள் தேவை.',
